+}
+.product-price {
+  display: flex;
+  align-items: baseline;
+  gap: 8px;
+  margin-top: auto;
+  padding-top: 8px;
+}
+.price-now {
+  font-size: 18px;
+  font-weight: 700;
+  color: var(--text);
+}
+.price-was {
