/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.15s, transform 0.15s;
  position: relative;
}
.product-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-3px);
}
.product-media {
  aspect-ratio: 1 / 1;
  position: relative;
  overflow: hidden;
  background: linear-gradient(160deg, #23232f, #14141b);
}
.product-media .swatch {
  position: absolute;
  inset: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 64px;
  filter: drop-shadow(0 12px 24px rgba(0,0,0,0.4));
}
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--bg);
  color: var(--text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
}
.product-tag.new { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.product-tag.sale { background: var(--danger); color: #1a0303; border-color: var(--danger); }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11,11,15,0.7);
  border: 1px solid var(--border);
  color: var(--text);
  cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  backdrop-filter: blur(4px);
}
.wishlist-btn:hover { color: var(--danger); border-color: var(--danger); }
.wishlist-btn[aria-pressed="true"] { color: var(--danger); border-color: var(--danger); }
.wishlist-btn[aria-pressed="true"] svg { fill: currentColor; }
.wishlist-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-cat {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-dim);
  font-weight: 600;
}
.product-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}
.product-title a { color: var(--text); }
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-muted);
}
.stars {
  color: var(--accent-strong);
  letter-spacing: 1px;
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: auto;
  padding-top: 8px;
}
.price-now {
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
}
.price-was {
  font-size: 14px;
  color: var(--text-dim);
  text-decoration: line-through;
}
.product-actions {
  display: flex;
  gap: 8px;
  padding: 0 16px 16px;
}
.btn-add {
  flex: 1;
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border-strong);
  padding: 10px 14px;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
}
.btn-add:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

/* ---------- Deals strip ---------- */
.deals {
  background:
    linear-gradient(135deg, rgba(255,180,84,0.10), rgba(138,180,255,0.06)),
    var(--bg-elev);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 32px;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  background: linear-gradient(160deg, #1f1a2e, #14141b);
}
.deal-card.feature {
  background:
    radial-gradient(600px 300px at 100% 0%, rgba(255,180,84,0.30), transparent 60%),
    linear-gradient(160deg, #2a1f33, #16121d);
}
.deal-card .kicker {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent-strong);
}
.deal-card h3 {
  margin: 10px 0 8px;
  font-size: clamp(1.25rem, 2.4vw, 1.75rem);
  line-height: 1.15;
  letter-spacing: -0.01em;
}
.deal-card p {
  margin: 0 0 18px;
  color: var(--text-muted);
  max-width: 38ch;
}
.deal-link {
  font-weight: 600;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.deal-link::after { content: "→"; transition: transform 0.15s; }
.deal-link:hover { color: var(--accent-strong); text-decoration: none; }
.deal-link:hover::after { transform: translateX(4px); }

/* Countdown */
.countdown {
  display: flex;
  gap: 10px;
  margin: 14px 0 18px;
}
.countdown-cell {
  background: rgba(0,0,0,0.4);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 8px 10px;
  text-align: center;
  min-width: 56px;
}
.countdown-cell strong {
  display: block;
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}
.countdown-cell span {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.15s, transform 0.15s;
}
.article-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-3px);
}
.article-media {
  aspect-ratio: 16 / 10;
  background: linear-gradient(160deg, #1f2433, #14141b);
  position: relative;
  overflow: hidden;
}
.article-media::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(420px 260px at 30% 30%, rgba(138,180,255,0.25), transparent 60%);
}
.article-card.tone-amber .article-media::after {
  background: radial-gradient(420px 260px at 70% 30%, rgba(255,180,84,0.30), transparent 60%);
}
.article-card.tone-rose .article-media::after {
  background: radial-gradient(420px 260px at 30% 70%, rgba(255,107,107,0.25), transparent 60%);
}
.article-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.article-cat {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--accent-strong);
  font-weight: 700;
  margin-bottom: 10px;
}
.article-card h3 {
  margin: 0 0 10px;
  font-size: 20px;
  line-height: 1.25;
  letter-spacing: -0.01em;
}
.article-card h3 a { color: var(--text); }
.article-card h3 a:hover { color: var(--accent-strong); text-decoration: none; }
.article-card p {
  color: var(--text-muted);
  margin: 0 0 16px;
}
.article-meta {
  margin-top: auto;
  font-size: 13px;
  color: var(--text-dim);
  display: flex;
  gap: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: linear-gradient(135deg, #1a1a24 0%, #0f0f17 100%);
  border-radius: var(--radius-lg);
  padding: 48px;
  border: 1px solid var(--border);
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
  margin: 24px 0;
}
.newsletter h2 {
  margin: 0 0 10px;
  font-size: clamp(1.5rem, 3vw, 2rem);
  letter-spacing: -0.01em;
}
.newsletter p { margin: 0; color: var(--text-muted); max-width: 50ch; }
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.newsletter-fields {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.newsletter label {
  font-size: 13px;
  color: var(--text-muted);
  font-weight: 500;
}
.newsletter .visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
.newsletter input[type="email"] {
  flex: 1;
  min-width: 0;
