/* ---------- Footer ---------- */
.site-footer {
  background: #07070a;
  border-top: 1px solid var(--border);
  padding: 56px 0 24px;
  color: var(--text-muted);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 32px;
}
.footer-grid h3 {
  font-size: 14px;
  margin: 0 0 14px;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 1px;
}
