+  color: var(--accent-ink);
+  font-size: 11px;
+  font-weight: 700;
+  border-radius: 10px;
+  display: inline-flex; align-items: center; justify-content: center;
+}
+
+.menu-toggle { display: none; }
+
+/* ---------- Hero ---------- */
+.hero {
+  position: relative;
+  border-bottom: 1px solid var(--border);
+  background:
+    radial-gradient(1200px 500px at 80% 0%, rgba(255,180,84,0.18), transparent 60%),
+    radial-gradient(900px 400px at 0% 100%, rgba(138,180,255,0.10), transparent 60%),
+    var(--bg);
+  overflow: hidden;
+}
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 48px;
+  align-items: center;
+  padding: 72px 24px 88px;
+}
+.hero-eyebrow {
+  display: inline-block;
+  text-transform: uppercase;
+  letter-spacing: 2px;
+  font-size: 12px;
+  color: var(--accent-strong);
+  font-weight: 700;
+  margin-bottom: 18px;
+  padding: 6px 12px;
+  border: 1px solid var(--border-strong);
+  border-radius: 999px;
+  background: var(--bg-elev);
+}
+.hero h1 {
+  font-size: clamp(2rem, 5vw, 3.5rem);
+  line-height: 1.05;
+  margin: 0 0 18px;
+  letter-spacing: -0.02em;
+  font-weight: 800;
+}
+.hero h1 em {
+  font-style: normal;
+  background: linear-gradient(135deg, var(--accent), #ff7a59);
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+}
+.hero p.lede {
+  font-size: 1.125rem;
+  color: var(--text-muted);
+  margin: 0 0 32px;
+  max-width: 56ch;
+}
+.hero-cta {
+  display: flex;
+  gap: 12px;
+  flex-wrap: wrap;
+}
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 14px 22px;
+  border-radius: 10px;
+  font-weight: 600;
+  font-size: 15px;
+  cursor: pointer;
+  border: 1px solid transparent;
+  text-decoration: none;
+  transition: transform 0.05s ease;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+.btn-primary:hover { background: var(--accent-strong); border-color: var(--accent-strong); text-decoration: none; }
+.btn-secondary {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+.btn-secondary:hover { background: var(--bg-elev); text-decoration: none; }
+
+.hero-meta {
+  margin-top: 36px;
+  display: flex;
+  gap: 32px;
+  flex-wrap: wrap;
+  color: var(--text-muted);
+  font-size: 14px;
+}
+.hero-meta strong { color: var(--text); display: block; font-size: 18px; }
+
+.hero-art {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  border-radius: var(--radius-lg);
+  background:
+    linear-gradient(160deg, #2a2236 0%, #1a1a26 60%, #14141b 100%);
+  border: 1px solid var(--border);
+  overflow: hidden;
+  box-shadow: var(--shadow-2);
+}
+.hero-art::after {
+  content: "";
+  position: absolute; inset: 0;
+  background:
+    radial-gradient(420px 260px at 70% 30%, rgba(255,180,84,0.35), transparent 60%),
+    radial-gradient(360px 240px at 20% 80%, rgba(138,180,255,0.20), transparent 60%);
+  pointer-events: none;
+}
+.hero-art-content {
+  position: absolute;
+  inset: auto 24px 24px 24px;
+  background: rgba(20,20,27,0.85);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  padding: 16px 18px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  backdrop-filter: blur(6px);
+}
+.hero-art-content .pill {
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-weight: 700;
+  font-size: 12px;
+  padding: 4px 10px;
+  border-radius: 999px;
+}
+
+/* ---------- Section ---------- */
+.section {
+  padding: 72px 0;
+  border-bottom: 1px solid var(--border);
+}
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+.section-head h2 {
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  margin: 0 0 6px;
+  letter-spacing: -0.01em;
+}
+.section-head p {
+  margin: 0;
+  color: var(--text-muted);
+  max-width: 60ch;
+}
+.section-link {
+  font-weight: 600;
+  color: var(--accent-strong);
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  white-space: nowrap;
+}
+
+/* ---------- Categories ---------- */
+.categories {
+  display: grid;
+  grid-template-columns: repeat(6, 1fr);
+  gap: 16px;
+}
+.category-card {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 10px;
+  padding: 22px 12px;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  color: var(--text);
+  font-weight: 500;
+  font-size: 14px;
+  text-align: center;
+  transition: border-color 0.15s, background 0.15s, transform 0.15s;
+}
+.category-card:hover {
+  background: var(--bg-elev-2);
+  border-color: var(--border-strong);
+  text-decoration: none;
+  transform: translateY(-2px);
+}
+.category-icon {
+  width: 44px; height: 44px;
+  border-radius: 12px;
+  background: linear-gradient(135deg, #2a2a3a, #1d1d27);
+  border: 1px solid var(--border-strong);
+  display: inline-flex; align-items: center; justify-content: center;
+  color: var(--accent-strong);
+}
+.category-icon svg { width: 22px; height: 22px; }
+
+/* ---------- Product grid ---------- */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 20px;
+}
+.product-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.15s, transform 0.15s;
+  position: relative;
+}
+.product-card:hover {
+  border-color: var(--border-strong);
+  transform: translateY(-3px);
+}
+.product-media {
+  aspect-ratio: 1 / 1;
+  position: relative;
+  overflow: hidden;
+  background: linear-gradient(160deg, #23232f, #14141b);
+}
+.product-media .swatch {
+  position: absolute;
+  inset: 0;
+  display: flex; align-items: center; justify-content: center;
+  font-size: 64px;
+  filter: drop-shadow(0 12px 24px rgba(0,0,0,0.4));
+}
+.product-tag {
+  position: absolute;
+  top: 12px; left: 12px;
+  background: var(--bg);
+  color: var(--text);
+  font-size: 11px;
+  font-weight: 700;
+  letter-spacing: 0.5px;
+  text-transform: uppercase;
+  padding: 5px 9px;
+  border-radius: 999px;
+  border: 1px solid var(--border-strong);
+}
+.product-tag.new { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+.product-tag.sale { background: var(--danger); color: #1a0303; border-color: var(--danger); }
+
+.wishlist-btn {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  background: rgba(11,11,15,0.7);
+  border: 1px solid var(--border);
+  color: var(--text);
+  cursor: pointer;
+  display: inline-flex; align-items: center; justify-content: center;
+  backdrop-filter: blur(4px);
+}
+.wishlist-btn:hover { color: var(--danger); border-color: var(--danger); }
+.wishlist-btn[aria-pressed="true"] { color: var(--danger); border-color: var(--danger); }
+.wishlist-btn[aria-pressed="true"] svg { fill: currentColor; }
+.wishlist-btn svg { width: 18px; height: 18px; }
+
+.product-body {
+  padding: 16px;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: 1px;
+  color: var(--text-dim);
+  font-weight: 600;
+}
+.product-title {
+  margin: 0;
+  font-size: 16px;
+  font-weight: 600;
+  line-height: 1.3;
+}
+.product-title a { color: var(--text); }
+.product-rating {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 13px;
+  color: var(--text-muted);
+}
+.stars {
+  color: var(--accent-strong);
+  letter-spacing: 1px;
+}
+.product-price {
+  display: flex;
+  align-items: baseline;
+  gap: 8px;
+  margin-top: auto;
+  padding-top: 8px;
+}
+.price-now {
+  font-size: 18px;
+  font-weight: 700;
+  color: var(--text);
+}
+.price-was {
+  font-size: 14px;
+  color: var(--text-dim);
+  text-decoration: line-through;
+}
+.product-actions {
+  display: flex;
+  gap: 8px;
+  padding: 0 16px 16px;
+}
+.btn-add {
+  flex: 1;
+  background: var(--bg-elev-2);
+  color: var(--text);
+  border: 1px solid var(--border-strong);
+  padding: 10px 14px;
+  border-radius: 10px;
+  font-weight: 600;
+  cursor: pointer;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  font-size: 14px;
+}
+.btn-add:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+
+/* ---------- Deals strip ---------- */
+.deals {
+  background:
+    linear-gradient(135deg, rgba(255,180,84,0.10), rgba(138,180,255,0.06)),
+    var(--bg-elev);
+}
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.3fr 1fr 1fr;
+  gap: 20px;
+}
+.deal-card {
+  position: relative;
+  border-radius: var(--radius-lg);
+  border: 1px solid var(--border);
+  padding: 32px;
+  min-height: 260px;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  overflow: hidden;
+  background: linear-gradient(160deg, #1f1a2e, #14141b);
+}
+.deal-card.feature {
+  background:
+    radial-gradient(600px 300px at 100% 0%, rgba(255,180,84,0.30), transparent 60%),
+    linear-gradient(160deg, #2a1f33, #16121d);
+}
+.deal-card .kicker {
+  font-size: 12px;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 2px;
+  color: var(--accent-strong);
+}
+.deal-card h3 {
+  margin: 10px 0 8px;
+  font-size: clamp(1.25rem, 2.4vw, 1.75rem);
+  line-height: 1.15;
+  letter-spacing: -0.01em;
+}
+.deal-card p {
+  margin: 0 0 18px;
+  color: var(--text-muted);
+  max-width: 38ch;
+}
+.deal-link {
+  font-weight: 600;
+  color: var(--text);
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+}
+.deal-link::after { content: "→"; transition: transform 0.15s; }
+.deal-link:hover { color: var(--accent-strong); text-decoration: none; }
+.deal-link:hover::after { transform: translateX(4px); }
+
+/* Countdown */
+.countdown {
+  display: flex;
+  gap: 10px;
+  margin: 14px 0 18px;
+}
+.countdown-cell {
+  background: rgba(0,0,0,0.4);
+  border: 1px solid var(--border-strong);
+  border-radius: 8px;
+  padding: 8px 10px;
+  text-align: center;
+  min-width: 56px;
+}
+.countdown-cell strong {
+  display: block;
+  font-size: 22px;
+  font-variant-numeric: tabular-nums;
+  font-weight: 700;
+}
+.countdown-cell span {
+  font-size: 11px;
+  color: var(--text-muted);
+  text-transform: uppercase;
+  letter-spacing: 1px;
+}
+
+/* ---------- Editorial ---------- */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 24px;
+}
+.article-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.15s, transform 0.15s;
+}
+.article-card:hover {
+  border-color: var(--border-strong);
+  transform: translateY(-3px);
+}
+.article-media {
+  aspect-ratio: 16 / 10;
+  background: linear-gradient(160deg, #1f2433, #14141b);
+  position: relative;
+  overflow: hidden;
+}
+.article-media::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: radial-gradient(420px 260px at 30% 30%, rgba(138,180,255,0.25), transparent 60%);
+}
+.article-card.tone-amber .article-media::after {
+  background: radial-gradient(420px 260px at 70% 30%, rgba(255,180,84,0.30), transparent 60%);
+}
+.article-card.tone-rose .article-media::after {
+  background: radial-gradient(420px 260px at 30% 70%, rgba(255,107,107,0.25), transparent 60%);
+}
+.article-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
+.article-cat {
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: 1.5px;
+  color: var(--accent-strong);
+  font-weight: 700;
+  margin-bottom: 10px;
+}
+.article-card h3 {
+  margin: 0 0 10px;
+  font-size: 20px;
+  line-height: 1.25;
+  letter-spacing: -0.01em;
+}
+.article-card h3 a { color: var(--text); }
+.article-card h3 a:hover { color: var(--accent-strong); text-decoration: none; }
+.article-card p {
+  color: var(--text-muted);
+  margin: 0 0 16px;
+}
+.article-meta {
+  margin-top: auto;
+  font-size: 13px;
+  color: var(--text-dim);
+  display: flex;
+  gap: 12px;
+  padding-top: 8px;
+  border-top: 1px solid var(--border);
+}
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  background: linear-gradient(135deg, #1a1a24 0%, #0f0f17 100%);
+  border-radius: var(--radius-lg);
+  padding: 48px;
+  border: 1px solid var(--border);
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 40px;
+  align-items: center;
+  margin: 24px 0;
+}
+.newsletter h2 {
+  margin: 0 0 10px;
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  letter-spacing: -0.01em;
+}
+.newsletter p { margin: 0; color: var(--text-muted); max-width: 50ch; }
+.newsletter-form {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+}
+.newsletter-fields {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+.newsletter label {
+  font-size: 13px;
+  color: var(--text-muted);
+  font-weight: 500;
+}
+.newsletter .visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+.newsletter input[type="email"] {
+  flex: 1;
+  min-width: 0;
+  background: var(--bg);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  padding: 14px 16px;
+  border-radius: 10px;
+  font-size: 15px;
+  font-family: inherit;
+}
+.newsletter input[type="email"]:focus {
+  outline: 2px solid var(--focus);
+  outline-offset: 2px;
+  border-color: var(--focus);
+}
+.newsletter input[aria-invalid="true"] {
+  border-color: var(--danger);
+}
+.newsletter .field-help {
+  font-size: 13px;
+  color: var(--text-muted);
+}
+.newsletter .field-error {
+  font-size: 13px;
+  color: var(--danger);
+  display: none;
+}
+.newsletter .field-error.visible { display: block; }
+.newsletter .form-status {
+  font-size: 14px;
+  color: var(--success);
+  min-height: 20px;
+}
+
+/* ---------- Trust strip ---------- */
+.trust {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 16px;
+  padding: 32px 0;
+}
+.trust-item {
+  display: flex;
+  gap: 14px;
+  align-items: flex-start;
+  padding: 16px;
+  border-radius: var(--radius);
+  border: 1px solid var(--border);
+  background: var(--bg-elev);
+}
+.trust-item .ti-icon {
+  width: 40px; height: 40px;
+  border-radius: 10px;
+  background: var(--bg-elev-2);
+  border: 1px solid var(--border-strong);
+  display: inline-flex; align-items: center; justify-content: center;
+  color: var(--accent-strong);
+  flex-shrink: 0;
+}
+.trust-item h3 { margin: 0 0 4px; font-size: 15px; }
+.trust-item p { margin: 0; font-size: 13px; color: var(--text-muted); }
+
+/* ---------- Footer ---------- */
+.site-footer {
+  background: #07070a;
+  border-top: 1px solid var(--border);
+  padding: 56px 0 24px;
+  color: var(--text-muted);
+}
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.4fr repeat(4, 1fr);
+  gap: 32px;
+}
+.footer-grid h3 {
+  font-size: 14px;
+  margin: 0 0 14px;
+  color: var(--text);
+  text-transform: uppercase;
+  letter-spacing: 1px;
+}
+.footer-grid ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
+.footer-grid a { color: var(--text-muted); font-size: 14px; }
+.footer-grid a:hover { color: var(--accent-strong); }
+.footer-brand p { margin: 12px 0 16px; max-width: 36ch; font-size: 14px; }
+.socials { display: flex; gap: 8px; }
+.socials a {
+  width: 38px; height: 38px;
+  border-radius: 10px;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  display: inline-flex; align-items: center; justify-content: center;
+  color: var(--text);
+}
+.socials a:hover { background: var(--bg-elev-2); border-color: var(--border-strong); color: var(--accent-strong); text-decoration: none; }
+.socials svg { width: 18px; height: 18px; }
+
+.footer-bottom {
+  margin-top: 40px;
+  padding-top: 20px;
+  border-top: 1px solid var(--border);
+  display: flex; justify-content: space-between; gap: 16px;
+  flex-wrap: wrap;
+  font-size: 13px;
+}
+
+/* ---------- Toast / live region ---------- */
+.toast-container {
+  position: fixed;
+  bottom: 20px; right: 20px;
+  display: flex; flex-direction: column; gap: 8px;
+  z-index: 200;
+  pointer-events: none;
+}
+.toast {
+  background: var(--bg-elev-2);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  padding: 12px 18px;
+  border-radius: 10px;
+  box-shadow: var(--shadow-2);
+  font-size: 14px;
+  pointer-events: auto;
+  animation: slideIn 0.2s ease-out;
+}
+@keyframes slideIn {
+  from { opacity: 0; transform: translateY(8px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+
+/* ---------- Responsive ---------- */
+@media (max-width: 960px) {
+  .hero-inner { grid-template-columns: 1fr; padding: 48px 24px; gap: 32px; }
+  .header-inner { grid-template-columns: auto auto; }
+  .menu-toggle {
+    display: inline-flex;
+  }
+  .primary-nav {
+    grid-column: 1 / -1;
+    display: none;
+  }
+  .primary-nav.open { display: block; }
+  .primary-nav ul { flex-direction: column; gap: 2px; padding: 8px 0; }
+  .primary-nav a { display: block; }
+  .product-grid { grid-template-columns: repeat(3, 1fr); }
+  .categories { grid-template-columns: repeat(3, 1fr); }
+  .deals-grid { grid-template-columns: 1fr; }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .trust { grid-template-columns: 1fr 1fr; }
+  .newsletter { grid-template-columns: 1fr; padding: 32px; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+
+@media (max-width: 640px) {
+  .container { padding: 0 16px; }
+  .section { padding: 48px 0; }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .categories { grid-template-columns: repeat(2, 1fr); }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .trust { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr; }
+  .hero h1 { font-size: 2rem; }
+  .hero-meta { gap: 20px; }
+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .btn, .btn-add, .icon-btn, .category-card, .product-card, .article-card,
+  .deal-card, .trust-item, .newsletter, .countdown-cell, .wishlist-btn {
+    border: 1px solid CanvasText;
+  }
+  .btn-primary { background: ButtonText; color: ButtonFace; }
+  .cart-badge { background: Highlight; color: HighlightText; border: 1px solid CanvasText; }
+  .product-tag { border: 1px solid CanvasText; }
+  .hero h1 em { color: CanvasText; -webkit-text-fill-color: CanvasText; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * { transition: none !important; animation: none !important; }
