const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toasts, setToasts] = useState([]);

  const pushToast = useCallback((message) => {
    const id = Date.now() + Math.random();
    setToasts(t => [...t, { id, message }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3000);
  }, []);

  const handleAdd = useCallback((p) => {
    setCart(c => [...c, p.id]);
    pushToast(`Added to bag: ${p.name}`);
  }, [pushToast]);

  const handleWishlist = useCallback((id) => {
    setWishlist(w => {
      const next = new Set(w);
      if (next.has(id)) {
        next.delete(id);
        pushToast('Removed from wishlist');
      } else {
        next.add(id);
        pushToast('Saved to wishlist');
      }
      return next;
    });
  }, [pushToast]);

  return h(React.Fragment, null,
    h('a', { href: '#main', className: 'skip-link' }, 'Skip to main content'),
    h(TopBar),
    h(Header, { cartCount: cart.length, onCartOpen: () => pushToast(`You have ${cart.length} item${cart.length === 1 ? '' : 's'} in your bag`) }),
