      h(Featured, { onAdd: handleAdd, onWishlist: handleWishlist, wishlist }),
      h(Deals),
      h(Editorial),
      h(Newsletter),
      h(Trust)
    ),
    h(Footer),
    h(Toasts, { items: toasts })
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(h(App));
