const Countdown = ({ targetMs }) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const remaining = Math.max(0, targetMs - now);
  const d = Math.floor(remaining / 86400000);
  const hh = Math.floor((remaining % 86400000) / 3600000);
  const mm = Math.floor((remaining % 3600000) / 60000);
  const ss = Math.floor((remaining % 60000) / 1000);
  const cell = (n, label) => h('div', { className: 'countdown-cell' },
    h('strong', null, String(n).padStart(2, '0')),
    h('span', null, label)
  );
  return h('div', {
    className: 'countdown',
    role: 'timer',
    'aria-live': 'off',
    'aria-label': `Sale ends in ${d} days, ${hh} hours, ${mm} minutes`
  }, cell(d, 'days'), cell(hh, 'hrs'), cell(mm, 'min'), cell(ss, 'sec'));
};

