const Newsletter = () => {
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');
  const inputRef = useRef(null);
  const onSubmit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
    if (!ok) {
      setError('Please enter a valid email address (e.g. you@example.com).');
      setStatus('');
      inputRef.current && inputRef.current.focus();
      return;
    }
    setError('');
    setStatus(`Thanks — we\u2019ll send your first dispatch to ${email.trim()} shortly.`);
    setEmail('');
  };
  return h('section', { className: 'section', 'aria-labelledby': 'news-heading' },
    h('div', { className: 'container' },
      h('div', { className: 'newsletter' },
        h('div', null,
          h('h2', { id: 'news-heading' }, 'Quiet inbox, considered drops.'),
          h('p', null, 'One thoughtful dispatch a month — new arrivals, journal stories, and member-only previews. No spam, ever.')
        ),
