          h('label', { htmlFor: 'news-email' }, 'Email address ', h('span', { 'aria-hidden': true, style: { color: 'var(--accent-strong)' } }, '*')),
          h('div', { className: 'newsletter-fields' },
            h('input', {
              ref: inputRef,
              id: 'news-email',
              type: 'email',
              required: true,
              'aria-required': 'true',
              'aria-invalid': error ? 'true' : 'false',
              'aria-describedby': error ? 'news-error news-help' : 'news-help',
              placeholder: 'you@example.com',
              autoComplete: 'email',
              value: email,
              onChange: e => { setEmail(e.target.value); if (error) setError(''); }
            }),
            h('button', { className: 'btn btn-primary', type: 'submit' }, 'Subscribe')
          ),
          h('div', { id: 'news-help', className: 'field-help' }, 'We respect your inbox. Unsubscribe with one click.'),
